contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= depositAmount, "test contract needs enough balance");

        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balanceBeforeWithdraw = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool withdrew;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        uint balanceAfterWithdraw = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(withdrew ? balanceAfterWithdraw == 0 : balanceAfterWithdraw == balanceBeforeWithdraw);
    }

    receive() external payable {}
}

