// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        try c.addToBalance{value: depositAmount}() {} catch { return; }
        uint256 balanceBeforeWithdraw;
        try c.getBalance(address(this)) returns (uint256 __r) { balanceBeforeWithdraw = __r; } catch { return; }
        bool withdrew;
        try c.withdrawBalance() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint256 balanceAfterWithdraw;
        try c.getBalance(address(this)) returns (uint256 __r) { balanceAfterWithdraw = __r; } catch { return; }
        assertTrue(withdrew ? balanceAfterWithdraw == 0 : balanceAfterWithdraw == balanceBeforeWithdraw);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
